def estimate_cost(usage, prices):
    tin = usage.get("input_tokens", 0)
    tout = usage.get("output_tokens", 0)
    if tin < 0 or tout < 0:
        raise ValueError("token counts must be non-negative")
    cost = tin * prices["input"] / 1_000_000 + tout * prices["output"] / 1_000_000
    return round(cost, 6)

code.tests:
p = {"input": 3.0, "output": 15.0}
assert estimate_cost({"input_tokens": 1000, "output_tokens": 500}, p) == 0.0105, "1000 input + 500 output phải ra 0.0105"
assert estimate_cost({"input_tokens": 1_000_000}, p) == 3.0, "thiếu output_tokens thì coi là 0, 1 triệu input phải ra 3.0"
assert estimate_cost({}, p) == 0.0, "không có token nào thì chi phí bằng 0"
assert estimate_cost({"output_tokens": 2_000_000}, {"input": 1.0, "output": 4.0}) == 8.0, "2 triệu output giá 4.0 phải ra 8.0"
try:
    estimate_cost({"input_tokens": -5}, p)
    assert False, "token âm phải raise ValueError"
except ValueError:
    pass

