def fake_model(history):
    last = history[-1]
    if last["role"] == "user":
        return {"action": "tool", "name": "multiply", "args": {"a": 6, "b": 7}}
    return {"action": "final", "answer": f"Result is {last['content']}"}

tools = {"multiply": lambda a, b: a * b}
assert run_agent(fake_model, tools, "6 x 7?", 5) == "Result is 42", "agent phải gọi multiply rồi trả lời Result is 42"

def stuck_model(history):
    return {"action": "tool", "name": "multiply", "args": {"a": 1, "b": 1}}
assert run_agent(stuck_model, tools, "loop", 3) == "stopped: max steps", "mô hình kẹt phải dừng ở max_steps"

calls = []
def counting_model(history):
    calls.append(len(history))
    return {"action": "tool", "name": "multiply", "args": {"a": 2, "b": 2}}
run_agent(counting_model, tools, "count", 4)
assert calls == [1, 2, 3, 4], "mỗi bước history phải dài thêm đúng 1 quan sát"

def bad_tool_model(history):
    if history[-1]["role"] == "user":
        return {"action": "tool", "name": "teleport", "args": {}}
    return {"action": "final", "answer": history[-1]["content"]}
assert run_agent(bad_tool_model, tools, "go", 5) == "error: unknown tool", "công cụ lạ phải tạo quan sát error: unknown tool"

def direct_model(history):
    return {"action": "final", "answer": "hi"}
assert run_agent(direct_model, tools, "hello", 1) == "hi", "trả lời ngay ở bước đầu thì không cần gọi công cụ"

