def normalize(s):
    return " ".join(s.lower().split())

def evaluate(cases):
    if not cases:
        return 0.0
    passed = 0
    for c in cases:
        out = normalize(c["output"])
        exp = normalize(c["expected"])
        if c["mode"] == "exact":
            ok = out == exp
        elif c["mode"] == "contains":
            ok = exp in out
        else:
            raise ValueError("unknown mode")
        passed += ok
    return round(passed / len(cases), 2)
